<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
class AccountReportController extends Controller {
 public function index(Request $r){
 $u=$r->user(); abort_unless($u->status && $u->school_id,403); $s=$u->school_id;
 $v=$r->validate(['report'=>'nullable|in:cashflow,daybook,ledger,cash,bank,trial,income,balance,vendors,salary,fees,expenses','from'=>'nullable|date_format:Y-m-d','to'=>'nullable|date_format:Y-m-d','account_id'=>'nullable|integer','format'=>'nullable|in:csv,print']);
 $report=$v['report']??'cashflow';$from=$v['from']??now()->startOfMonth()->toDateString();$to=$v['to']??now()->toDateString();abort_if($from>$to,422);
 $names=['cashflow'=>'Operational receipts and payments','daybook'=>'Posted journal day book','ledger'=>'General ledger','cash'=>'Cash book','bank'=>'Bank book','trial'=>'Trial balance','income'=>'Ledger income and expenditure','balance'=>'Ledger balance sheet','vendors'=>'Vendor outstanding (as of end date)','salary'=>'Salary outstanding (as of end date)','fees'=>'Fee receipts','expenses'=>'Expense payments by category'];
 $table=fn($t)=>DB::table($t)->where('school_id',$s);$accounts=$table('account_ledger_accounts')->orderBy('code')->get();$rows=[];$note='';
 $lines=fn()=>DB::table('account_journal_lines as l')->join('account_journals as j','j.id','=','l.journal_id')->join('account_ledger_accounts as a','a.id','=','l.account_id')->where('j.school_id',$s)->where('a.school_id',$s)->where('j.status','posted');
 $period=fn($q,$col)=>$q->whereBetween($col,[$from,$to]);
 if($report==='cashflow'){$headers=['Description','Amount'];$in=$period($table('fee_collections')->where('status','posted'),'payment_date')->sum('total_amount');$out=[];foreach(['Expense payments'=>'account_expense_payments','Vendor payments'=>'account_vendor_payments','Salary payments'=>'account_salary_payments'] as $label=>$t)$out[$label]=$period($table($t),'payment_date')->sum('amount');$rows[]=['Gross fee receipts',$in];foreach($out as $k=>$n)$rows[]=[$k,$n];$rows[]=['Receipts less recorded payments',round($in-array_sum($out),2)];$note='Operational totals only; excludes refunds, other income and outflows. Not a bank balance. Do not add these totals to ledger totals.';}
 elseif(in_array($report,['daybook','ledger','cash','bank'])){ $headers=['Date','Journal','Account','Description','Debit','Credit'];$q=$lines();if(in_array($report,['cash','bank']))$q->where('a.type',$report);if(!empty($v['account_id'])){abort_unless($accounts->contains('id',$v['account_id']),422);$q->where('a.id',$v['account_id']);}$opening=(clone $q)->where('j.entry_date','<',$from)->selectRaw('COALESCE(SUM(l.debit-l.credit),0) n')->first()->n;foreach($period($q,'j.entry_date')->orderBy('j.entry_date')->orderBy('j.id')->orderBy('l.id')->get(['j.entry_date','j.id','a.name','j.description','l.debit','l.credit']) as $x)$rows[]=array_values((array)$x);$note='Posted manual ledger entries only. Opening net debit balance for selected accounts: '.$opening;}
 elseif(in_array($report,['trial','income','balance'])){$headers=['Account','Type','Debit','Credit','Net debit'];$q=$lines()->where('j.entry_date','<=',$to);if($report==='income')$q->where('j.entry_date','>=',$from)->whereIn('a.type',['income','expense']);$data=$q->groupBy('a.id','a.code','a.name','a.type')->selectRaw('a.code,a.name,a.type,SUM(l.debit) d,SUM(l.credit) c')->orderBy('a.code')->get();$d=0;$c=0;$profit=0;foreach($data as $x){$n=round($x->d-$x->c,2);if($report==='balance' && in_array($x->type,['income','expense'])){$profit-=$n;continue;}$debit=max(0,$n);$credit=max(0,-$n);$rows[]=[$x->code.' '.$x->name,$x->type,$debit,$credit,$n];$d+=$debit;$c+=$credit;}if($report==='balance'){$rows[]=['Accumulated unclosed earnings','equity',max(0,-$profit),max(0,$profit),-$profit];$d+=max(0,-$profit);$c+=max(0,$profit);}$rows[]=['Total','',round($d,2),round($c,2),round($d-$c,2)];$note='Posted ledger only. Trial balance and balance sheet include all entries through end date; income report uses selected period. Unclosed earnings are included in balance sheet.';}
 elseif($report==='vendors'){$headers=['Vendor','Invoice','Amount','Paid','Outstanding'];$q=DB::table('account_vendor_invoices as i')->join('account_vendors as a','a.id','=','i.vendor_id')->where('i.school_id',$s)->where('a.school_id',$s)->whereIn('i.status',['approved','partial','paid'])->where('i.invoice_date','<=',$to)->whereDate('i.reviewed_at','<=',$to)->select('a.name','i.invoice_number','i.amount')->selectSub($table('account_vendor_payments')->whereColumn('invoice_id','i.id')->where('payment_date','<=',$to)->selectRaw('COALESCE(SUM(amount),0)'),'paid');foreach($q->get() as $x)if($x->amount>$x->paid)$rows[]=[$x->name,$x->invoice_number,$x->amount,$x->paid,round($x->amount-$x->paid,2)];}
 elseif($report==='salary'){$headers=['Employee','Month','Net salary','Paid','Outstanding'];$q=DB::table('hr_payslips as p')->join('hr_payroll_runs as r','r.id','=','p.payroll_run_id')->join('users as u','u.id','=','p.user_id')->where('p.school_id',$s)->where('r.school_id',$s)->where('u.school_id',$s)->where('r.status','finalized')->whereDate('r.finalized_at','<=',$to)->select('u.name','p.pay_month','p.net_salary')->selectSub($table('account_salary_payments')->whereColumn('payslip_id','p.id')->where('payment_date','<=',$to)->selectRaw('COALESCE(SUM(amount),0)'),'paid');foreach($q->get() as $x)if($x->net_salary>$x->paid)$rows[]=[$x->name,$x->pay_month,$x->net_salary,$x->paid,round($x->net_salary-$x->paid,2)];}
 elseif($report==='fees'){$headers=['Date','Receipt','Mode','Amount'];foreach($period($table('fee_collections')->where('status','posted'),'payment_date')->orderBy('payment_date')->get(['payment_date','receipt_no','payment_mode','total_amount']) as $x)$rows[]=array_values((array)$x);$note='Gross posted receipts, excluding refunds.';}
 else {$headers=['Category','Amount'];$q=DB::table('account_expense_payments as p')->join('account_expenses as e','e.id','=','p.expense_id')->join('account_expense_categories as c','c.id','=','e.category_id')->where('p.school_id',$s)->where('e.school_id',$s)->where('c.school_id',$s);foreach($period($q,'p.payment_date')->groupBy('c.id','c.name')->selectRaw('c.name,SUM(p.amount) amount')->get() as $x)$rows[]=array_values((array)$x);}
 if(($v['format']??'')==='csv')return response()->streamDownload(function()use($headers,$rows,$note){$f=fopen('php://output','w');fwrite($f,"\xEF\xBB\xBF");fputcsv($f,$headers);foreach($rows as $row)fputcsv($f,array_map(fn($x)=>is_string($x)&&!is_numeric($x)&&preg_match('/^[\s=+@-]/u',$x)?"'".$x:$x,$row));if($note)fputcsv($f,[$note]);fclose($f);},$report.'-'.$to.'.csv',['Content-Type'=>'text/csv']);
 return view('accounts.reports',compact('names','report','from','to','accounts','headers','rows','note','v'));
 }
}
